mapper.select:
SELECT ID, PERSON_ID, TAG_ID, SOURCE_TYPE AS SOURCE, STATUS, RULE_ID, BATCH_NO,
       MATCHED_KEYWORD, REVIEWED_BY, REVIEWED_AT, CREATED_AT, UPDATED_AT
FROM PT_PERSON_TAG WHERE PERSON_ID = #{personId} AND TAG_ID = #{tagId}

mapper.update:
UPDATE PT_PERSON_TAG SET SOURCE_TYPE = #{source}, STATUS = #{status}, RULE_ID = #{ruleId},
    BATCH_NO = #{batchNo}, MATCHED_KEYWORD = #{matchedKeyword}, REVIEWED_BY = #{reviewedBy},
    REVIEWED_AT = #{reviewedAt}, UPDATED_AT = #{updatedAt}
WHERE ID = #{id}

UPDATE PT_PERSON_TAG SET STATUS = #{status}, REVIEWED_BY = #{reviewer},
    REVIEWED_AT = #{reviewedAt}, UPDATED_AT = #{reviewedAt}
WHERE ID = #{id}

mapper.delete:
DELETE FROM PT_PERSON_TAG WHERE PERSON_ID = #{personId} AND SOURCE_TYPE = 'RULE' AND STATUS != 'REJECTED'
AND TAG_ID NOT IN
#{tagId}
